  END IF;

END $$;


-- Insert Quiz Questions for Lesson: Why Opportunities & Pipelines Matter

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 5 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 5 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'why-opportunities-pipelines-matter' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson why-opportunities-pipelines-matter not found in module 5';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why do most leads get lost?', 
    '["Because they said no","Because nobody followed up, the lead stayed in inbox, or the next step was forgotten","Because they were not interested","Because the price was too high"]'::jsonb,
    'Because nobody followed up, the lead stayed in inbox, or the next step was forgotten',
    'Most leads are lost due to lack of follow-up, not because of price or interest. They get buried in the inbox or the next step is forgotten.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What does the pipeline show?', 
    '["Email conversations","Business status and where leads are in the sales process","Social media posts","Website analytics"]'::jsonb,
    'Business status and where leads are in the sales process',
    'The pipeline shows business status - where each lead stands in the sales process. The inbox shows conversations, but the pipeline shows the sales journey.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should happen when someone shows interest?', 
    '["Let them stay in the inbox","Add them as an Opportunity for proper follow-up","Delete their message","Wait for them to contact again"]'::jsonb,
    'Add them as an Opportunity for proper follow-up',
    'When someone shows interest, they should be added as an Opportunity so they can be properly tracked and followed up with, not left in the inbox.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


