-- Insert Quiz Questions for Lesson: What Is a Pipeline?

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 5 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 5 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'what-is-pipeline' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson what-is-pipeline not found in module 5';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is a Pipeline?', 
    '["A list of email templates","The path a lead moves through from first interest to final decision","A social media strategy","A type of contact form"]'::jsonb,
    'The path a lead moves through from first interest to final decision',
    'A Pipeline is the path a lead moves through from first interest to final decision. It visualizes the sales journey with stages like New Lead, Contacted, Appointment Booked, etc.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What does the ''Lost'' stage mean?', 
    '["You failed as a salesperson","The lead is not moving forward right now in this pipeline","The lead should be deleted forever","You should never contact them again"]'::jsonb,
    'The lead is not moving forward right now in this pipeline',
    'Lost does not mean failure. It simply means the lead is not moving forward in this pipeline right now. They may re-engage later or be suited for a different offer.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Which stage comes after ''Contacted''?', 
    '["Won","Appointment Booked","Lost","New Lead"]'::jsonb,
    'Appointment Booked',
    'The typical flow is: New Lead → Contacted → Appointment Booked → Proposal Sent → Won/Lost. After Contacted comes Appointment Booked.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


