-- Insert Quiz Questions for Lesson: Finding the Opportunities Area

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 5 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 5 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'finding-opportunities-area' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson finding-opportunities-area not found in module 5';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where does sales tracking live in LeadProspectrr?', 
    '["In the Settings menu","In the Opportunities area","In the Reports section only","In the email inbox"]'::jsonb,
    'In the Opportunities area',
    'The Opportunities area is where sales tracking lives in LeadProspectrr. It displays leads as cards in different pipeline stages.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What can you see on the Opportunities board?', 
    '["Only contact names","Pipeline name, stages, lead cards, values, status, notes, and assigned users","Only email messages","Social media feeds"]'::jsonb,
    'Pipeline name, stages, lead cards, values, status, notes, and assigned users',
    'The Opportunities board shows: pipeline name, stage columns, lead cards, contact names, opportunity value, status, notes, assigned user, and stage movement options.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What question can the board help you answer?', 
    '["What is the weather today?","Who is new, who has been contacted, who booked a call, who needs a proposal","What to have for lunch","How to write code"]'::jsonb,
    'Who is new, who has been contacted, who booked a call, who needs a proposal',
    'The board helps answer sales questions: Who is new? Who has been contacted? Who has booked a call? Who needs a proposal? Who has said yes? Who is no longer moving forward?', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


