-- Insert Quiz Questions for Lesson: Moving Leads Through the Pipeline

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 5 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 5 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'moving-leads-pipeline' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson moving-leads-pipeline not found in module 5';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'When should you move a lead to the ''Contacted'' stage?', 
    '["When they first show interest","When you have replied, called, texted, or emailed them","When they pay","Never"]'::jsonb,
    'When you have replied, called, texted, or emailed them',
    'Move a lead to Contacted when you have actively reached out to them - by replying, calling, texting, or emailing. This shows the lead has been contacted, not just that they showed interest.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why is moving leads through the pipeline important?', 
    '["It makes the board look colorful","It helps you avoid guessing and know what needs attention","It is required by law","It deletes old leads"]'::jsonb,
    'It helps you avoid guessing and know what needs attention',
    'Moving leads through the pipeline gives you visual clarity. You can look at the board and immediately know what needs attention - who is new, who has been contacted, who needs a proposal, etc.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do when a lead says yes to your offer?', 
    '["Delete the Opportunity","Move them to the ''Won'' stage","Leave them in ''New Lead''","Move them to ''Lost''"]'::jsonb,
    'Move them to the ''Won'' stage',
    'When a lead agrees to move forward and becomes a client, move them to the ''Won'' stage. This tracks your successful conversions and clears them from active follow-up stages.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


