-- Insert Quiz Questions for Lesson: Adding Notes and Next Steps

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 5 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 5 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'adding-notes-next-steps' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson adding-notes-next-steps not found in module 5';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What three things do you need for good follow-up?', 
    '["Name, email, phone","Stage, note, and next step","Price, discount, invoice","Social media, website, ads"]'::jsonb,
    'Stage, note, and next step',
    'You need three things: the pipeline stage (where they are), a note (what happened), and a next step (what to do next). All three are essential for good follow-up.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What makes a good note?', 
    '["Just the person''s name","Details about what they want, what was discussed, deadlines, and next actions","A single word like ''Called''","Your opinion about their personality"]'::jsonb,
    'Details about what they want, what was discussed, deadlines, and next actions',
    'A good note includes details: what the lead asked for, what service they want, what was discussed, any deadlines, pricing concerns, and the next promised action.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why are next steps important?', 
    '["They are not important","A lead without a next step is easy to forget","They automatically send emails","They delete old leads"]'::jsonb,
    'A lead without a next step is easy to forget',
    'Next steps are crucial because a lead without a defined next action is easy to forget. Clear next steps ensure consistent follow-up.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


