-- Insert Quiz Questions for Lesson: Daily Pipeline Check-In

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 5 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 5 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'daily-pipeline-check-in' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson daily-pipeline-check-in not found in module 5';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'How long should a daily pipeline check-in take?', 
    '["At least 2 hours","About five minutes","All day","It is not necessary"]'::jsonb,
    'About five minutes',
    'A daily pipeline check-in only takes about five minutes. This short time investment prevents leads from being forgotten.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the simple rule for closing the pipeline?', 
    '["Close it whenever you want","Never close the pipeline if an active lead has no next step","Always delete old leads first","Only check it once per month"]'::jsonb,
    'Never close the pipeline if an active lead has no next step',
    'The simple rule: Never close the pipeline if an active lead has no next step. This ensures every lead has a defined follow-up action.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do during the daily check-in?', 
    '["Only look at new leads","Review all stages, move changed leads, add notes, set next actions","Delete all old opportunities","Nothing, just close it"]'::jsonb,
    'Review all stages, move changed leads, add notes, set next actions',
    'During the daily check-in: review New Leads, Contacted, Appointment Booked, Proposal Sent; move anything that changed; add notes; set next follow-up actions.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


